        x: cx + 0.28, y: cy + 2.46 + j * 0.38, w: cw - 0.45, h: 0.3,
        fontSize: 9.5, fontFace: "Calibri", color: C.charcoal, margin: 0
      });
    });
  });

  // Global callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.18, w: 9, h: 0.38,
    fill: { color: C.red, transparency: 10 }
  });
  slide.addText("Globally, not everyone has access to vaccines. Supply shortages and declining trust put children and communities at risk.", {
    x: 0.6, y: 5.18, w: 8.8, h: 0.38,
    fontSize: 10.5, fontFace: "Calibri", color: C.red,
    align: "left", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: Roush & Murphy (2007) via Our World in Data  •  OurWorldInData.org/vaccination", {
    x: 0.5, y: 5.58, w: 9, h: 0.2,
    fontSize: 9, fontFace: "Calibri", color: C.muted, margin: 0
  });
}

// ============================================================
// SLIDE 8: Takeaways and Priorities
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top decorative bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.mint }
  });

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.28, w: 9, h: 0.6,
    fontSize: 34, fontFace: "Georgia", bold: true,
    color: C.white, margin: 0
  });
  slide.addText("Vaccines have eliminated deadly diseases — but the job isn't done", {
    x: 0.5, y: 0.88, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: C.mint, margin: 0
  });

  // Takeaway cards - 2x2 grid
  const takeaways = [
    {
      num: "01",
      title: "100% Elimination Achieved",
      body: "Diphtheria, smallpox, and both forms of polio have been eliminated in the US through vaccination — zero cases, zero deaths.",
      color: C.green,
    },
    {
      num: "02",
      title: "Development Timelines Collapsed",
      body: "From 105 years (typhoid) to under 1 year (COVID-19) — mRNA technology and genomic tools have revolutionized vaccine development speed.",
      color: C.teal,
    },
    {
      num: "03",
      title: "Herd Immunity Protects Communities",
      body: "When enough people are vaccinated, pathogens cannot spread effectively — shielding newborns, immunocompromised patients, and chemotherapy patients.",
      color: C.seafoam,
    },
    {
      num: "04",
      title: "Gaps Persist for Some Diseases",
      body: "Pneumococcal disease (40.5% reduction), hepatitis A (89%), and hepatitis B (83.9%) show incomplete control — access, coverage, and trust challenges remain.",
      color: C.accent,
    },
  ];

  takeaways.forEach((t, i) => {
    const tx = i % 2 === 0 ? 0.5 : 5.1;
    const ty = i < 2 ? 1.45 : 3.3;
    const tw = 4.4, th = 1.65;

    slide.addShape(pres.shapes.RECTANGLE, {
      x: tx, y: ty, w: tw, h: th,
      fill: { color: C.white, transparency: 8 },
      line: { color: t.color, width: 1 }
    });

    // Number
    slide.addText(t.num, {
      x: tx + 0.15, y: ty + 0.12, w: 0.55, h: 0.4,
      fontSize: 18, fontFace: "Georgia", bold: true,
      color: t.color, margin: 0
    });

    // Title
    slide.addText(t.title, {
      x: tx + 0.72, y: ty + 0.15, w: 3.5, h: 0.35,
      fontSize: 13, fontFace: "Calibri", bold: true,
      color: C.white, margin: 0
    });

    // Body
    slide.addText(t.body, {
      x: tx + 0.15, y: ty + 0.55, w: tw - 0.3, h: 1.0,
      fontSize: 10.5, fontFace: "Calibri", color: "CBD5E1",
      align: "left", valign: "top", margin: 0
    });
  });

  // Call to Action
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: C.mint, transparency: 15 }
  });
  slide.addText("Call to Action:  Improve global access, strengthen coverage, and build trust in vaccination to protect every community.", {
    x: 0.6, y: 5.05, w: 8.8, h: 0.45,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: C.mint, align: "left", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: Our World in Data  •  OurWorldInData.org/vaccination", {
    x: 0.5, y: 5.55, w: 9, h: 0.2,
    fontSize: 9, fontFace: "Calibri", color: "475569", margin: 0
  });
}

// Write file
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Presentation saved to /app/output/final_deck.pptx"))
  .catch(err => console.error("Error:", err));

