const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time";
pres.author = "Our World in Data";

// Color palette - Teal Trust for public health authority
const C = {
  teal: "028090",
  seafoam: "00A896",
  mint: "02C39A",
  darkBg: "0A2540",
  lightBg: "F8FAFB",
  white: "FFFFFF",
  charcoal: "1E293B",
  muted: "64748B",
  accent: "E85D04",
  red: "DC2626",
  green: "16A34A",
  lightTeal: "E0F2F1",
};

const makeShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ============================================================
// SLIDE 1: Title
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top decorative bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.mint }
  });

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.08, w: 0.06, h: 5.545, fill: { color: C.teal }
  });

  // Decorative circle top-right
  slide.addShape(pres.shapes.OVAL, {
    x: 8.0, y: -0.8, w: 3.5, h: 3.5,
    fill: { color: C.teal, transparency: 75 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 8.8, y: -0.2, w: 2.2, h: 2.2,
    fill: { color: C.seafoam, transparency: 80 }
  });

  // Main title
  slide.addText("The Power of Vaccination", {
    x: 0.6, y: 1.3, w: 8.8, h: 0.9,
    fontSize: 40, fontFace: "Georgia", bold: true,
    color: C.white, margin: 0
  });

  // Subtitle
  slide.addText("From Smallpox Eradication to COVID-19 in Record Time", {
    x: 0.6, y: 2.2, w: 8.5, h: 0.6,
    fontSize: 20, fontFace: "Calibri",
    color: C.mint, margin: 0
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 2.95, w: 3.5, h: 0.04, fill: { color: C.seafoam }
  });

  // Scope text
  slide.addText("A data-driven overview of vaccine impact across two centuries", {
    x: 0.6, y: 3.15, w: 7.5, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: "94A3B8", margin: 0
  });

  // Date range badge
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.75, w: 1.8, h: 0.45,
    fill: { color: C.teal, transparency: 30 },
    line: { color: C.seafoam, width: 1 }
  });
  slide.addText("1796 – 2020", {
    x: 0.6, y: 3.75, w: 1.8, h: 0.45,
    fontSize: 13, fontFace: "Calibri", bold: true,
    color: C.mint, align: "center", valign: "middle", margin: 0
  });

  // Source attribution
  slide.addText("Source: Our World in Data  •  OurWorldInData.org/vaccination", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: "475569", margin: 0
  });
}

// ============================================================
// SLIDE 2: Vaccine Timeline Acceleration
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("From 100 Years to Under 1 Year", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Georgia", bold: true,
    color: C.charcoal, margin: 0
  });
  slide.addText("Vaccine Development Is Accelerating", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri", color: C.muted, margin: 0
  });

  // Subtitle explanation
  slide.addText("Years from pathogen identification to vaccine licensure", {
    x: 0.5, y: 1.3, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.muted, italic: true, margin: 0
  });

  // Horizontal bar chart data
  const diseases = [
    { name: "Typhoid fever", years: 105, identified: 1884, licensed: 1989 },
    { name: "Meningitis", years: 92, identified: 1889, licensed: 1981 },
    { name: "Chickenpox", years: 42, identified: 1953, licensed: 1995 },
    { name: "Whooping cough", years: 42, identified: 1906, licensed: 1948 },
    { name: "Polio", years: 47, identified: 1908, licensed: 1955 },
    { name: "Ebola", years: 43, identified: 1976, licensed: 2019 },
    { name: "Measles", years: 10, identified: 1953, licensed: 1963 },
    { name: "Hepatitis B", years: 16, identified: 1965, licensed: 1981 },
    { name: "COVID-19", years: 0.8, identified: 2020, licensed: 2020, highlight: true },
  ];

  const chartX = 0.5;
  const chartY = 1.7;
  const chartW = 9;
  const chartH = 3.6;
  const barHeight = 0.34;
  const rowGap = 0.06;

  // Chart background card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: chartX, y: chartY, w: chartW, h: chartH,
    fill: { color: C.white }, shadow: makeShadow()
  });

  // Y-axis labels and bars
  diseases.forEach((d, i) => {
    const rowY = chartY + 0.25 + i * (barHeight + rowGap);
    const maxBarW = 6.5;
    const barW = d.highlight
      ? maxBarW
      : Math.max((d.years / 105) * maxBarW, 0.1);

    // Disease label
    slide.addText(d.name, {
      x: chartX + 0.15, y: rowY, w: 1.9, h: barHeight,
      fontSize: 10.5, fontFace: "Calibri", bold: d.highlight,
      color: d.highlight ? C.teal : C.charcoal,
      align: "left", valign: "middle", margin: 0
    });

    // Bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: chartX + 2.1, y: rowY + 0.04, w: barW, h: barHeight - 0.08,
      fill: { color: d.highlight ? C.teal : (d.years > 40 ? "CBD5E1" : "94A3B8") }
    });

    // Year count label
    const labelText = d.highlight ? "<1 yr" : `${d.years} yrs`;
    slide.addText(labelText, {
      x: chartX + 2.15 + barW, y: rowY, w: 0.8, h: barHeight,
      fontSize: 10, fontFace: "Calibri", bold: d.highlight,
      color: d.highlight ? C.teal : C.muted,
      align: "left", valign: "middle", margin: 0
    });

    // Year range
    slide.addText(`${d.identified} → ${d.licensed}`, {
      x: chartX + 5.8, y: rowY, w: 1.6, h: barHeight,
      fontSize: 9, fontFace: "Calibri", color: C.muted,
      align: "left", valign: "middle", margin: 0
    });
  });

  // COVID-19 callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: chartY + 0.2, w: 2.6, h: 0.55,
    fill: { color: C.teal, transparency: 10 },
    line: { color: C.teal, width: 1.5 }
  });
  slide.addText("COVID-19: <1 year\nRecord pace enabled by\nmRNA & genomic tools", {
    x: 6.75, y: chartY + 0.22, w: 2.5, h: 0.52,
    fontSize: 9, fontFace: "Calibri", bold: true,
    color: C.teal, align: "center", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: Our World in Data  •  OurWorldInData.org/vaccination", {
    x: 0.5, y: 5.25, w: 9, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: C.muted, margin: 0
  });
}

// ============================================================
// SLIDE 3: US Disease Elimination
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox in the US", {
    x: 0.5, y: 0.28, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Georgia", bold: true,
    color: C.charcoal, margin: 0
  });
  slide.addText("Pre-vaccine vs. post-vaccine annual case and death rates per million population, US", {
    x: 0.5, y: 0.88, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.muted, margin: 0
  });

  // Table data
  const headers = [
    { text: "Disease", options: { bold: true, color: C.white, fill: { color: C.teal }, align: "left" } },
    { text: "Pre-Vaccine\nCases /M", options: { bold: true, color: C.white, fill: { color: C.teal }, align: "center" } },
    { text: "Post-Vaccine\nCases /M", options: { bold: true, color: C.white, fill: { color: C.teal }, align: "center" } },
    { text: "Case\nReduction", options: { bold: true, color: C.white, fill: { color: C.teal }, align: "center" } },
    { text: "Pre-Vaccine\nDeaths /M", options: { bold: true, color: C.white, fill: { color: C.teal }, align: "center" } },
    { text: "Death\nReduction", options: { bold: true, color: C.white, fill: { color: C.teal }, align: "center" } },
  ];

  const diseases = [
    { name: "Diphtheria", preCases: "158", postCases: "0", reduction: "100%", preDeaths: "13.7", deathRed: "100%", fullElim: true },
    { name: "Measles", preCases: "3,044", postCases: "0.2", reduction: "99.99%", preDeaths: "2.5", deathRed: "100%", fullElim: false },
    { name: "Smallpox", preCases: "250", postCases: "0", reduction: "100%", preDeaths: "2.9", deathRed: "100%", fullElim: true },
    { name: "Acute polio", preCases: "141", postCases: "0", reduction: "100%", preDeaths: "10", deathRed: "100%", fullElim: true },
    { name: "Pertussis", preCases: "1,534", postCases: "52", reduction: "96.6%", preDeaths: "30.8", deathRed: "99.7%", fullElim: false },
    { name: "Rubella", preCases: "242", postCases: "0.04", reduction: "99.98%", preDeaths: "0.09", deathRed: "100%", fullElim: false },
    { name: "Hepatitis A", preCases: "465", postCases: "51", reduction: "89%", preDeaths: "0.5", deathRed: "88.7%", fullElim: false },
    { name: "Acute hep. B", preCases: "273", postCases: "44", reduction: "83.9%", preDeaths: "1", deathRed: "83.6%", fullElim: false },
    { name: "Pneumococcal", preCases: "233", postCases: "139", reduction: "40.5%", preDeaths: "24", deathRed: "31.3%", fullElim: false },
  ];

  const tableRows = [headers];
  diseases.forEach((d, i) => {
    const rowFill = d.fullElim
      ? { color: "DCFCE7" }
      : i % 2 === 0
        ? { color: C.white }
        : { color: "F1F5F9" };

    const reductionColor = d.fullElim ? C.green : d.reduction === "40.5%" ? C.red : C.charcoal;

    tableRows.push([
      { text: d.name, options: { fill: rowFill, color: C.charcoal, align: "left", bold: d.fullElim } },
      { text: d.preCases, options: { fill: rowFill, color: C.charcoal, align: "center" } },
      { text: d.postCases, options: { fill: rowFill, color: C.charcoal, align: "center" } },
      { text: d.reduction, options: { fill: rowFill, color: reductionColor, align: "center", bold: d.fullElim } },
      { text: d.preDeaths, options: { fill: rowFill, color: C.charcoal, align: "center" } },
      { text: d.deathRed, options: { fill: rowFill, color: reductionColor, align: "center", bold: d.fullElim } },
    ]);
  });

  slide.addTable(tableRows, {
    x: 0.4, y: 1.25, w: 9.2, h: 3.85,
    fontFace: "Calibri", fontSize: 10,
    colW: [1.8, 1.3, 1.3, 1.2, 1.3, 1.2],
    rowH: 0.4,
    border: { pt: 0.5, color: "E2E8F0" },
    valign: "middle",
  });

  // Legend callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 5.15, w: 0.18, h: 0.18,
    fill: { color: "DCFCE7" }, line: { color: C.green, width: 1 }
  });
  slide.addText("= 100% elimination of cases and deaths", {
    x: 0.65, y: 5.1, w: 3.5, h: 0.28,
    fontSize: 10, fontFace: "Calibri", color: C.green, margin: 0
  });

  // Source
  slide.addText("Source: Roush & Murphy (2007) via Our World in Data  •  OurWorldInData.org/vaccination", {
    x: 0.5, y: 5.35, w: 9, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: C.muted, margin: 0
  });
}

// ============================================================
// SLIDE 4: Measles Heatmap States
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("Measles Cases Collapsed Across All 50 US States After Vaccine Mandates", {
    x: 0.5, y: 0.28, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Georgia", bold: true,
    color: C.charcoal, margin: 0
  });
  slide.addText("Measles incidence per 100,000 population, 1929–2022", {
    x: 0.5, y: 0.88, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.muted, margin: 0
  });

  // Legend bar for heatmap (manual visualization)
  const hmX = 0.5, hmY = 1.3, hmW = 5.8, hmH = 3.7;
  const decades = ["1920s", "1930s", "1940s", "1950s", "1960s", "1970s", "1980s", "1990s", "2000s", "2010s", "2020s"];
  const decadesHigh = [true, true, true, true, true, false, false, false, false, false, false];

  // Heatmap background card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: hmX, y: hmY, w: hmW, h: hmH,
    fill: { color: C.white }, shadow: makeShadow()
  });

  // Simulated heatmap rows (states grouped, showing intensity by decade)
  const decades2 = [
    { label: "1920s–1962", color: "B91C1C", desc: "Pre-vaccine era" },
    { label: "1963–1970", color: "F97316", desc: "Early vaccination" },
    { label: "1971–1979", color: "FCD34D", desc: "MMR introduced" },
    { label: "1980–1999", color: "86EFAC", desc: "Post-mandate" },
    { label: "2000–2022", color: "166534", desc: "Near elimination" },
  ];

  decades2.forEach((d, i) => {
    const rowY = hmY + 0.2 + i * 0.68;
    const barW = i < 2 ? 4.0 : i === 2 ? 2.5 : i === 3 ? 1.5 : 0.8;

    // Decade label
    slide.addText(d.label, {
      x: hmX + 0.12, y: rowY, w: 1.3, h: 0.5,
      fontSize: 10, fontFace: "Calibri", bold: true,
      color: C.charcoal, align: "left", valign: "middle", margin: 0
    });

    // Heat intensity bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: hmX + 1.5, y: rowY + 0.1, w: barW, h: 0.32,
      fill: { color: d.color }
    });

    // Description
    slide.addText(d.desc, {
      x: hmX + 1.5 + barW + 0.1, y: rowY, w: 2.5, h: 0.5,
      fontSize: 10, fontFace: "Calibri", color: C.muted,
      align: "left", valign: "middle", margin: 0
    });
  });

  // Legend for heatmap colors
  const legendItems = [
    { color: "B91C1C", label: "100–1,000+ per 100K (endemic)" },
    { color: "F97316", label: "10–100 per 100K" },
    { color: "FCD34D", label: "1–10 per 100K" },
    { color: "86EFAC", label: "<1 per 100K (controlled)" },
    { color: "166534", label: "Near zero (eliminated)" },
  ];

  const legendX = 6.5, legendY = 1.3;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: legendX, y: legendY, w: 3.1, h: 2.2,
    fill: { color: C.white }, shadow: makeShadow()
  });

  slide.addText("Incidence Scale", {
    x: legendX + 0.1, y: legendY + 0.05, w: 2.9, h: 0.35,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: C.charcoal, margin: 0
  });

  legendItems.forEach((item, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: legendX + 0.1, y: legendY + 0.45 + i * 0.36, w: 0.28, h: 0.22,
      fill: { color: item.color }
    });
    slide.addText(item.label, {
      x: legendX + 0.45, y: legendY + 0.42 + i * 0.36, w: 2.55, h: 0.3,
      fontSize: 9, fontFace: "Calibri", color: C.charcoal,
      align: "left", valign: "middle", margin: 0
    });
  });

  // Milestone annotations
  const milestones = [
    { year: "1963", desc: "First measles vaccine\nby John Enders" },
    { year: "1971", desc: "MMR vaccine\nby Maurice Hilleman" },
    { year: "1980", desc: "Kindergarten\nvaccination mandate" },
  ];

  milestones.forEach((m, i) => {
    const mx = 6.5 + i * 1.05;
    const my = 3.7;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: mx, y: my, w: 0.95, h: 1.1,
      fill: { color: C.teal }, shadow: makeShadow()
    });
    slide.addText(m.year, {
      x: mx, y: my + 0.06, w: 0.95, h: 0.32,
      fontSize: 14, fontFace: "Georgia", bold: true,
      color: C.white, align: "center", valign: "middle", margin: 0
    });
    slide.addText(m.desc, {
      x: mx + 0.04, y: my + 0.38, w: 0.87, h: 0.65,
      fontSize: 8, fontFace: "Calibri",
      color: C.white, align: "center", valign: "top", margin: 0
    });
  });

  // Key insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: C.teal, transparency: 10 }
  });
